const MOD = 1e9 + 7;

function modMul(x, y) {
    return ((x * y) % MOD + MOD) % MOD;
}

function modPlus(x, y) {
    return (x + y) % MOD;
}

function solve() {
    const input = require('fs').readFileSync(0, 'utf8');
    const tokens = input.split(/\s+/);
    let ptr = 0;

    function readInt() {
        return parseInt(tokens[ptr++]);
    }

    const n = readInt();
    const m = readInt();
    const musics = [];
    const cnts = [0, 0, 0, 0];

    for (let i = 0; i < n; i++) {
        const a = readInt();
        const b = readInt();
        musics.push([a, b]);
        cnts[b]++;
    }

    const c1 = cnts[1];
    const c2 = cnts[2];
    const c3 = cnts[3];

    // comp[i][j][k][t]
    const comp = new Array(c1 + 1);
    for (let i = 0; i <= c1; i++) {
        comp[i] = new Array(c2 + 1);
        for (let j = 0; j <= c2; j++) {
            comp[i][j] = new Array(c3 + 1);
            for (let k = 0; k <= c3; k++) {
                comp[i][j][k] = new Array(4).fill(0);
            }
        }
    }

    for (let i = 0; i <= c1; i++) {
        for (let j = 0; j <= c2; j++) {
            for (let k = 0; k <= c3; k++) {
                for (let t = 0; t < 4; t++) {
                    if (i === 0 && j === 0 && k === 0) {
                        comp[i][j][k][t] = 1;
                        continue;
                    }
                    if (i > 0 && t !== 1) {
                        comp[i][j][k][t] = modPlus(comp[i][j][k][t], modMul(comp[i - 1][j][k][1], i));
                    }
                    if (j > 0 && t !== 2) {
                        comp[i][j][k][t] = modPlus(comp[i][j][k][t], modMul(comp[i][j - 1][k][2], j));
                    }
                    if (k > 0 && t !== 3) {
                        comp[i][j][k][t] = modPlus(comp[i][j][k][t], modMul(comp[i][j][k - 1][3], k));
                    }
                }
            }
        }
    }

    // last[i][j][k][t] and next[i][j][k][t]
    const last = new Array(c1 + 1);
    const next = new Array(c1 + 1);
    for (let i = 0; i <= c1; i++) {
        last[i] = new Array(c2 + 1);
        next[i] = new Array(c2 + 1);
        for (let j = 0; j <= c2; j++) {
            last[i][j] = new Array(c3 + 1);
            next[i][j] = new Array(c3 + 1);
            for (let k = 0; k <= c3; k++) {
                last[i][j][k] = new Array(m + 1).fill(0);
                next[i][j][k] = new Array(m + 1).fill(0);
            }
        }
    }

    last[0][0][0][0] = 1;
    let t1 = 0;
    let t2 = 0;
    let t3 = 0;

    for (const music of musics) {
        const m0 = music[0];
        const m1 = music[1];

        if (m1 === 1) {
            t1++;
        } else if (m1 === 2) {
            t2++;
        } else {
            t3++;
        }

        for (let i = 0; i <= t1; i++) {
            for (let j = 0; j <= t2; j++) {
                for (let k = 0; k <= t3; k++) {
                    for (let t = 0; t <= m; t++) {
                        next[i][j][k][t] = last[i][j][k][t];
                        if (t < m0) {
                            continue;
                        }
                        if (m1 === 1 && i > 0) {
                            next[i][j][k][t] = modPlus(next[i][j][k][t], last[i - 1][j][k][t - m0]);
                        } else if (m1 === 2 && j > 0) {
                            next[i][j][k][t] = modPlus(next[i][j][k][t], last[i][j - 1][k][t - m0]);
                        } else if (m1 === 3 && k > 0) {
                            next[i][j][k][t] = modPlus(next[i][j][k][t], last[i][j][k - 1][t - m0]);
                        }
                    }
                }
            }
        }

        // Swap last and next
        for (let i = 0; i <= c1; i++) {
            for (let j = 0; j <= c2; j++) {
                for (let k = 0; k <= c3; k++) {
                    for (let t = 0; t <= m; t++) {
                        last[i][j][k][t] = next[i][j][k][t];
                    }
                }
            }
        }
    }

    let ans = 0;
    for (let i = 0; i <= c1; i++) {
        for (let j = 0; j <= c2; j++) {
            for (let k = 0; k <= c3; k++) {
                ans = modPlus(ans, modMul(last[i][j][k][m], comp[i][j][k][0]));
            }
        }
    }

    console.log(ans);
}

