        let sign = 1;
        while (this.index < this.data.length && this.data[this.index] <= ' ') {
            this.index++;
        }
        if (this.index < this.data.length && (this.data[this.index] === '+' || this.data[this.index] === '-')) {
            sign = this.data[this.index] === '+' ? 1 : -1;
            this.index++;
        }
        let val = 0;
        if (sign === 1) {
            while (this.index < this.data.length && this.data[this.index] >= '0' && this.data[this.index] <= '9') {
